/**
 * Local, non-durable ID helpers.
 *
 * Durable business IDs (messages, conversations, chats, agents, ...) are always
 * generated by the backend as Snowflake IDs. These helpers are only for UI
 * objects, attachments in an in-flight draft, terminal panes, and request tokens.
 */

let localIdCounter = 0

const PERSISTED_MESSAGE_ID_PATTERN = /^msg_(\d+)_(\d+)_(\d+)$/

/**
 * Check whether an ID was issued by the backend as a persisted message ID.
 *
 * Optimistic UI messages may use locally generated IDs and must not be sent as
 * client request IDs. Only backend-issued `msg_` Snowflake IDs may participate
 * in durable deduplication.
 */
export function isPersistedMessageId(value: unknown): value is string {
  if (typeof value !== "string") return false

  const match = PERSISTED_MESSAGE_ID_PATTERN.exec(value)
  if (!match) return false

  const [, timestamp, instance, sequence] = match
  if (timestamp.length > 15 || instance.length > 4 || sequence.length > 4) {
    return false
  }

  return Number(instance) <= 1023 && Number(sequence) <= 4095
}

/** Return random bytes as lowercase hex. This is not a UUID. */
export function randomToken(byteLength = 16): string {
  const bytes = new Uint8Array(byteLength)
  globalThis.crypto.getRandomValues(bytes)
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("")
}

/** Create a unique local identifier with an optional readable prefix. */
export function createLocalId(prefix?: string): string {
  // Increment counter; overflow is not a concern in practice since
  // Number.MAX_SAFE_INTEGER is 9 quadrillion.
  localIdCounter += 1
  const time = Date.now().toString(36)
  const counter = localIdCounter.toString(36)
  const random = randomToken(8)
  return prefix ? `${prefix}_${time}_${counter}_${random}` : `${time}_${counter}_${random}`
}
